export const RADIO_STATIONS=[{id:'garage',name:'Kettenfett FM',tag:'Gummiente im Funk-Getriebe',bpm:112,root:48,wave:'triangle',melody:[12,15,19,15,22,19,15,10,12,0,19,22,24,19,15,10]},{id:'tropical',name:'Papagei Paradise',tag:'Offbeat statt Abflug',bpm:126,root:50,wave:'sine',melody:[16,19,21,19,16,14,12,0,16,19,24,21,19,16,14,12]},{id:'space',name:'Kosmos-Kasper',tag:'Disco für außerirdische Hüften',bpm:132,root:45,wave:'square',melody:[12,19,24,19,15,22,27,22,17,24,29,24,15,22,27,19]}];
export const ENGINE_SOUNDS=[{id:'v2',name:'V2 · Blubberbox'},{id:'race',name:'Racing · Krawalltüte'},{id:'electric',name:'Elektro · Space-Surren'}];
export function normalizeAudioSettings(value={}){const volume=(key,fallback)=>Number.isFinite(Number(value[key]))?Math.min(1,Math.max(0,Number(value[key]))):fallback;return {music:volume('music',.35),voice:volume('voice',.9),engine:volume('engine',.75),musicMuted:!!value.musicMuted,voiceMuted:!!value.voiceMuted,engineMuted:!!value.engineMuted,station:RADIO_STATIONS.some(s=>s.id===value.station)?value.station:'garage',engineSound:ENGINE_SOUNDS.some(s=>s.id===value.engineSound)?value.engineSound:'v2'};}
export function channelVolume(settings,channel){return settings[channel+'Muted']?0:settings[channel];}
